import{c as a,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E5%9B%BE1-BlockReduceSum%E6%B1%82%E5%92%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.Beq5UjCj.png",m=JSON.parse('{"title":"BilinearInterpolation(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"BilinearInterpolation\\\\(ISASI\\\\)","slug":"bilinearinterpolationisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/基础算术/BilinearInterpolation(ISASI).md","filePath":"api/SIMD-API/基础API/Memory矢量计算/基础算术/BilinearInterpolation(ISASI).md"}'),i={name:"api/SIMD-API/基础API/Memory矢量计算/基础算术/BilinearInterpolation(ISASI).md"};function p(o,t,r,d,c,h){return s(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="bilinearinterpolation-isasi" tabindex="-1">BilinearInterpolation(ISASI) <a class="header-anchor" href="#bilinearinterpolation-isasi" aria-label="Permalink to &quot;BilinearInterpolation\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>功能分为水平迭代和垂直迭代。每个水平迭代顺序地从src0Offset读取8个偏移值，表示src0的偏移，每个偏移值指向src0的一个DataBlock的起始地址，如果repeatMode=false，从src1中取一个值，与src0中8个DataBlock中每个值进行乘操作；如果repeatMode=true，从src1中取8个值，按顺序与src0中8个DataBlock中的值进行乘操作，最后当前迭代的dst结果与前一个dst结果按DataBlock进行累加，存入目的地址，在同一个水平迭代内dst地址不变。然后进行垂直迭代，垂直迭代的dst起始地址为上一轮垂直迭代的dst起始地址加上vROffset，本轮垂直迭代占用dst空间为dst起始地址之后的8个DataBlock，每轮垂直迭代进行hRepeat次水平迭代。</p><p><img src="'+l+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>mask逐bit模式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void BilinearInterpolation(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src0, const LocalTensor&lt;uint32_t&gt;&amp; src0Offset, const LocalTensor&lt;T&gt;&amp; src1, uint64_t mask[], uint8_t hRepeat, bool repeatMode, uint16_t dstBlkStride, uint16_t vROffset, uint8_t vRepeat, const LocalTensor&lt;uint8_t&gt; &amp;sharedTmpBuffer)</span></span></code></pre></div></li><li><p>mask连续模式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void BilinearInterpolation(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src0, const LocalTensor&lt;uint32_t&gt;&amp; src0Offset, const LocalTensor&lt;T&gt;&amp; src1, uint64_t mask, uint8_t hRepeat, bool repeatMode, uint16_t dstBlkStride, uint16_t vROffset, uint8_t vRepeat, const LocalTensor&lt;uint8_t&gt; &amp;sharedTmpBuffer)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half。 Atlas 推理系列产品AI Core，支持的数据类型为：half。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src0、src1</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 两个源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>src0Offset</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>mask[]/mask</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</td></tr><tr><td>hRepeat</td><td>输入</td><td>水平方向迭代次数，取值范围为[1, 255]。</td></tr><tr><td>repeatMode</td><td>输入</td><td>迭代模式： false：每次迭代src0读取的8个datablock中每个值均与src1的单个数值相乘。true：每次迭代src0的每个datablock分别与src1的1个数值相乘，共消耗8个block和8个elements。</td></tr><tr><td>dstBlkStride</td><td>输入</td><td>单次迭代内，目的操作数不同DataBlock间地址步长，以32B为单位。</td></tr><tr><td>vROffset</td><td>输入</td><td>垂直迭代间，目的操作数地址偏移量，以元素为单位，取值范围为[128, 65535)，vROffset * sizeof(T)需要保证32字节对齐 。</td></tr><tr><td>vRepeat</td><td>输入</td><td>垂直方向迭代次数，取值范围为[1, 255]。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时空间。 Ascend 950PR/Ascend 950DT，不需要分配临时空间。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，需要保证至少分配了src0.GetSize() * 32 + src1.GetSize() * 32字节的空间。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，需要保证至少分配了src0.GetSize() * 32 + src1.GetSize() * 32字节的空间。 Atlas 推理系列产品AI Core，需要保证至少分配了src0OffsetLocal.GetSize() * sizeof(uint32_t)字节的空间。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>src0、src1、src0Offset之间不允许地址重叠，且两个垂直repeat的目的地址之间不允许地址重叠。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>更多样例可参考<a href="./更多样例-9.html">LINK</a>。</p><ul><li><p>接口样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal, src0Local, src1Local;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;uint32_t&gt; src0OffsetLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;uint8_t&gt; tmpLocal;</span></span>
<span class="line"><span>uint64_t mask = 128;        // mask连续模式</span></span>
<span class="line"><span>uint8_t hRepeat = 2;        // 水平迭代2次</span></span>
<span class="line"><span>bool repeatMode = false;    // 迭代模式</span></span>
<span class="line"><span>uint16_t dstBlkStride = 1;  // 单次迭代内数据连续写入</span></span>
<span class="line"><span>uint16_t vROffset = 128;    // 相邻迭代间数据连续写入</span></span>
<span class="line"><span>uint8_t vRepeat = 2;        // 垂直迭代2次</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::BilinearInterpolation(dstLocal, src0Local, src0OffsetLocal, src1Local, mask, hRepeat, repeatMode,</span></span>
<span class="line"><span>            dstBlkStride, vROffset, vRepeat, tmpLocal);</span></span></code></pre></div></li><li><p>接口样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal, src0Local, src1Local;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;uint32_t&gt; src0OffsetLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;uint8_t&gt; tmpLocal;</span></span>
<span class="line"><span>uint64_t mask[2] = { UINT64_MAX, UINT64_MAX }; // mask逐bit模式</span></span>
<span class="line"><span>uint8_t hRepeat = 2;        // 水平迭代2次</span></span>
<span class="line"><span>bool repeatMode = false;    // 迭代模式</span></span>
<span class="line"><span>uint16_t dstBlkStride = 1;  // 单次迭代内数据连续写入</span></span>
<span class="line"><span>uint16_t vROffset = 128;    // 相邻迭代间数据连续写入</span></span>
<span class="line"><span>uint8_t vRepeat = 2;        // 垂直迭代2次</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::BilinearInterpolation(dstLocal, src0Local, src0OffsetLocal, src1Local, mask, hRepeat, repeatMode,</span></span>
<span class="line"><span>            dstBlkStride, vROffset, vRepeat, tmpLocal);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(src0Local,half): [1,2,3,...,512]</span></span>
<span class="line"><span>输入数据(src1Local,half): [2,3,4,...,17]</span></span>
<span class="line"><span>输入数据(src0OffsetLocal,uint32_t): [0,32,64,...,992]</span></span>
<span class="line"><span>输出数据(dstLocal,half): [389, 394, 399, 404, ...,4096]</span></span></code></pre></div>`,22)])])}const f=a(i,[["render",p]]);export{m as __pageData,f as default};
